15	const EmailInboxCard = () => {
16	  const { user, profile, refreshProfile } = useAuth();
17	  const [togglingEmail, setTogglingEmail] = useState(false);
18	  const [copied, setCopied] = useState(false);
19	  const [howItWorksOpen, setHowItWorksOpen] = useState(false);
20	  const [regenerating, setRegenerating] = useState(false);
21	
22	  const handleCopyInbox = () => {
23	    if (profile?.inbox_email) {
24	      navigator.clipboard.writeText(profile.inbox_email);
25	      setCopied(true);
26	      toast.success("Inbox email copied to clipboard.");
27	      setTimeout(() => setCopied(false), 2000);
28	    }
29	  };
30	
31	  const handleRegenerateInbox = async () => {
32	    if (!user) return;
33	    setRegenerating(true);
34	    try {
35	      const { data, error } = await supabase.rpc("generate_user_inbox_email", { p_user_id: user.id });
36	      if (error) throw error;
37	      await refreshProfile();
38	      toast.success(`Inbox regenerated: ${data}`);
39	    } catch (e: any) {
40	      toast.error(e.message || "Failed to regenerate inbox");
41	    } finally {
42	      setRegenerating(false);
43	    }
44	  };
45	
46	  const handleToggleEmail = async (checked: boolean) => {
47	    if (!user) return;
48	    setTogglingEmail(true);
49	    const { error } = await supabase
50	      .from("profiles")
51	      .update({ email_enabled: checked })
52	      .eq("user_id", user.id);
53	    if (error) {
54	      toast.error(error.message);
55	    } else {
56	      await refreshProfile();
57	      toast.success(checked ? "Email enabled" : "Email disabled");
58	    }
59	    setTogglingEmail(false);
60	  };
61	
62	  return (
63	    <Card className="overflow-hidden">
64	      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
65	        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
66	          <Mail className="h-4.5 w-4.5 text-primary" />
67	        </div>
68	        <div>
69	          <h3 className="text-base font-semibold text-foreground">Email Inbox</h3>
70	          <p className="text-xs text-muted-foreground">
71	            Forward resumes here to auto-add them to your jobs.
