123	            No inbox email assigned yet.
124	          </div>
125	        )}
126	        <div className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
127	          <Label htmlFor="email-toggle" className="text-sm font-medium cursor-pointer">
128	            Email ingestion enabled
129	          </Label>
130	          <Switch
131	            id="email-toggle"
132	            checked={profile?.email_enabled ?? true}
133	            onCheckedChange={handleToggleEmail}
134	            disabled={togglingEmail}
135	          />
136	        </div>
137	
138	        {/* How it works */}
139	        <Collapsible open={howItWorksOpen} onOpenChange={setHowItWorksOpen}>
140	          <CollapsibleTrigger asChild>
141	            <Button variant="ghost" size="sm" className="w-full justify-between text-muted-foreground text-xs">
142	              <span className="flex items-center gap-1.5">
143	                <Info className="h-3.5 w-3.5" />
144	                How email ingestion works
145	              </span>
146	              <ChevronDown className={`h-3.5 w-3.5 transition-transform ${howItWorksOpen ? "rotate-180" : ""}`} />
147	            </Button>
148	          </CollapsibleTrigger>
149	          <CollapsibleContent className="pt-2">
150	            <div className="rounded-md bg-muted/50 p-3 text-xs text-muted-foreground space-y-2.5">
151	              <p><strong>Per-job inbox:</strong> Each job gets a unique email address (e.g. <code className="bg-muted px-1 py-0.5 rounded text-[11px]">you+j-abc123@inbound.rankora.co</code>). Forward resumes to it and they'll be attached directly to that job.</p>
152	              <p><strong>Fallback inbox:</strong> Your personal inbox above routes resumes to your most recent pending job. Use this when you don't need job-specific routing.</p>
153	              <p><strong>Routing priority:</strong> Job-specific inbox is checked first. If no match, the fallback inbox routes to your latest pending job. If no pending job exists, one is auto-created.</p>
