12	interface UsageLog {
13	  id: string;
14	  created_at: string;
15	  credits_used: number;
16	  job_id: string | null;
17	  job_title?: string | null;
18	}
19	
20	const PAGE_SIZE = 10;
21	
22	const UsageHistoryCard = () => {
23	  const { user } = useAuth();
24	  const [usageLogs, setUsageLogs] = useState<UsageLog[]>([]);
25	  const [loading, setLoading] = useState(true);
26	  const [page, setPage] = useState(0);
27	  const [hasMore, setHasMore] = useState(false);
28	  const [loadingMore, setLoadingMore] = useState(false);
29	
30	  const fetchLogs = async (pageNum: number, append = false) => {
31	    if (!user) return;
32	    if (pageNum === 0) setLoading(true);
33	    else setLoadingMore(true);
34	
35	    const { data } = await supabase
36	      .from("usage_logs")
37	      .select("id, created_at, credits_used, job_id")
38	      .eq("user_id", user.id)
39	      .order("created_at", { ascending: false })
40	      .range(pageNum * PAGE_SIZE, (pageNum + 1) * PAGE_SIZE - 1);
41	
42	    if (data) {
43	      setHasMore(data.length === PAGE_SIZE);
44	      const jobIds = [...new Set(data.map(l => l.job_id).filter(Boolean))] as string[];
45	      let jobTitles: Record<string, string | null> = {};
46	      if (jobIds.length > 0) {
47	        const { data: jobs } = await supabase.from("jobs").select("id, title").in("id", jobIds);
48	        if (jobs) jobs.forEach(j => { jobTitles[j.id] = j.title; });
49	      }
50	      const mapped = data.map(l => ({
51	        ...l,
52	        job_title: l.job_id ? (jobTitles[l.job_id] ?? "Untitled Job") : null,
53	      }));
54	      setUsageLogs(prev => append ? [...prev, ...mapped] : mapped);
55	    }
56	    setLoading(false);
57	    setLoadingMore(false);
58	  };
59	
60	  useEffect(() => {
61	    fetchLogs(0);
62	  }, [user]);
63	
64	  const loadMore = () => {
65	    const nextPage = page + 1;
66	    setPage(nextPage);
67	    fetchLogs(nextPage, true);
68	  };
69	
70	  return (
71	    <Card className="overflow-hidden">
72	      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
73	        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
74	          <History className="h-4.5 w-4.5 text-primary" />
75	        </div>
76	        <div>
77	          <h3 className="text-sm font-semibold text-foreground">Usage History</h3>
78	          <p className="text-xs text-muted-foreground">Your credit deductions.</p>
79	        </div>
80	      </div>
81	      <CardContent className="px-6 pt-3 pb-5">
82	        {loading ? (
83	          <div className="space-y-3">
84	            {[...Array(4)].map((_, i) => (
85	              <Skeleton key={i} className="h-12 w-full rounded-lg" />
86	            ))}
87	          </div>
88	        ) : usageLogs.length === 0 ? (
89	          <div className="text-center py-10">
90	            <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-accent">
91	              <Zap className="h-6 w-6 text-muted-foreground/40" />
92	            </div>
93	            <p className="text-sm text-muted-foreground">
94	              No credit usage yet. Start ranking resumes to see your history here.
95	            </p>
96	          </div>
97	        ) : (
98	          <div className="space-y-1">
99	            {usageLogs.map((log) => (
100	              <div
101	                key={log.id}
102	                className="flex items-center justify-between rounded-lg px-3 py-2.5 hover:bg-accent/50 transition-colors"
103	              >
104	                <div className="min-w-0">
105	                  <p className="text-sm font-medium text-foreground truncate">
106	                    {log.job_title ?? "No job linked"}
107	                  </p>
108	                  <p className="text-xs text-muted-foreground">
109	                    {new Date(log.created_at).toLocaleDateString("en-US", {
110	                      month: "short", day: "numeric", year: "numeric",
111	                      hour: "2-digit", minute: "2-digit"
112	                    })}
113	                  </p>
114	                </div>
115	                <Badge variant="secondary" className="gap-1 shrink-0 tabular-nums">
116	                  <Coins className="h-3 w-3" />
117	                  -{log.credits_used}
118	                </Badge>
119	              </div>
120	            ))}
121	          </div>
122	        )}
123	        {!loading && usageLogs.length > 0 && hasMore && (
124	          <div className="pt-3 text-center">
125	            <Button variant="outline" size="sm" onClick={loadMore} disabled={loadingMore}>
126	              {loadingMore ? "Loading…" : "Load more"}
127	            </Button>
128	          </div>
129	        )}
130	      </CardContent>
131	    </Card>
132	  );
133	};
134	
135	export default UsageHistoryCard;
